public typealias TermXPID = Int32
public struct SpawnRequest { public let cmdline:String; public let stdinFD:Int32; public let stdoutFD:Int32; public let stderrFD:Int32; public let cwd:String; public let env:[String:String]; public let interactive:Bool; public init(cmdline:String,stdinFD:Int32=-1,stdoutFD:Int32=-1,stderrFD:Int32=-1,cwd:String,env:[String:String]=[:],interactive:Bool=false){self.cmdline=cmdline;self.stdinFD=stdinFD;self.stdoutFD=stdoutFD;self.stderrFD=stderrFD;self.cwd=cwd;self.env=env;self.interactive=interactive} }
public protocol TerminalEngine { func startShell(cwd:String,env:[String:String],ptySlave:Int32,onExit:@escaping(Int32)->Void)throws->Int32; func signal(pid:Int32,_ sig:Int32) }
public final class CommandRegistry { public typealias Handler=([String],CommandContext)->Int32; private var handlers:[String:Handler]=[:]; public init(){registerDefaults()}; public func register(_ name:String,handler:@escaping Handler){handlers[name]=handler}; public var names:[String]{handlers.keys.sorted()}; public func execute(_ name:String,args:[String],context:CommandContext)->Int32{handlers[name]?(args,context) ?? 127}; private func registerDefaults(){register("echo"){a,c in c.write(a.joined(separator:" ")+"\n");return 0};register("pwd"){_,c in c.write(c.cwd+"\n");return 0};register("cd"){a,c in guard let t=a.first else{return 0};let p=t.hasPrefix("/") ? t : URL(fileURLWithPath:c.cwd).appendingPathComponent(t).standardized.path;var d:ObjCBool=false;guard FileManager.default.fileExists(atPath:p,isDirectory:&d),d.boolValue else{c.error("cd: no such directory: \(t)\n");return 1};c.cwd=p;return 0};register("ls"){a,c in let p=a.first.map{$0.hasPrefix("/") ? $0 : URL(fileURLWithPath:c.cwd).appendingPathComponent($0).path} ?? c.cwd;do{let x=try FileManager.default.contentsOfDirectory(atPath:p).sorted();c.write(x.joined(separator:"  ")+(x.isEmpty ? "":"\n"));return 0}catch{c.error("ls: \(error.localizedDescription)\n");return 1}};register("cat"){a,c in guard !a.isEmpty else{c.error("cat: missing operand\n");return 1};var s:Int32=0;for f in a{let p=f.hasPrefix("/") ? f : URL(fileURLWithPath:c.cwd).appendingPathComponent(f).path;do{c.write(try String(contentsOfFile:p,encoding:.utf8))}catch{c.error("cat: \(f): \(error.localizedDescription)\n");s=1}};return s};register("mkdir"){a,c in var s:Int32=0;for f in a{do{try FileManager.default.createDirectory(at:URL(fileURLWithPath:c.cwd).appendingPathComponent(f),withIntermediateDirectories:false)}catch{c.error("mkdir: \(error.localizedDescription)\n");s=1}};return s};register("touch"){a,c in var s:Int32=0;for f in a{if !FileManager.default.createFile(atPath:URL(fileURLWithPath:c.cwd).appendingPathComponent(f).path,contents:Data()){s=1}};return s};register("rm"){a,c in var s:Int32=0;for f in a{do{try FileManager.default.removeItem(at:URL(fileURLWithPath:c.cwd).appendingPathComponent(f))}catch{c.error("rm: \(error.localizedDescription)\n");s=1}};return s};register("env"){_,c in c.write(c.env.sorted{$0.key<$1.key}.map{"\($0.key)=\($0.value)"}.joined(separator:"\n")+"\n");return 0};register("true"){_,_ in 0};register("false"){_,_ in 1};register("clear"){_,c in c.write("\u{1b}[2J\u{1b}[H");return 0};register("help"){_,c in c.write("TermX shell built-ins: \(c.registry.names.joined(separator:", "))\n");return 0} } }
public final class CommandContext { public var cwd:String; public var env:[String:String]; public let registry:CommandRegistry; private let output:(String)->Void; private let errorOutput:(String)->Void; public init(cwd:String,env:[String:String],registry:CommandRegistry,output:@escaping(String)->Void,error:@escaping(String)->Void){self.cwd=cwd;self.env=env;self.registry=registry;self.output=output;self.errorOutput=error}; public func write(_ value:String){output(value)};public func error(_ value:String){errorOutput(value)} }
public struct ShellParser { public init(){}; public func tokenize(_ line:String)->[String]{var r:[String]=[];var c="";var q:Character?;var e=false;for ch in line{if e{c.append(ch);e=false;continue};if ch=="\\" && q != "'"{e=true;continue};if let z=q{if ch==z{q=nil}else{c.append(ch)};continue};if ch=="'" || ch=="\""{q=ch;continue};if ch==" " || ch=="\t"{if !c.isEmpty{r.append(c);c=""}}else{c.append(ch)}};if !c.isEmpty{r.append(c)};return r} }
public final class ShellCore:TerminalEngine { public let registry:CommandRegistry;private let parser=ShellParser();private var nextPID:TermXPID=100;private var jobs:[TermXPID:DispatchWorkItem]=[:];private let lock=NSLock();public init(registry:CommandRegistry=CommandRegistry()){self.registry=registry};public func run(_ line:String,cwd:inout String,env:inout[String:String],output:@escaping(String)->Void,error:@escaping(String)->Void)->Int32{var status:Int32=0;for p in line.split(separator:";",omittingEmptySubsequences:true).map(String.init){status=runSingle(p.trimmingCharacters(in:.whitespaces),cwd:&cwd,env:&env,output:output,error:error)};return status};private func runSingle(_ line:String,cwd:inout String,env:inout[String:String],output:@escaping(String)->Void,error:@escaping(String)->Void)->Int32{if line.isEmpty{return 0};let t=parser.tokenize(line);guard let n=t.first else{return 0};var a=Array(t.dropFirst());var file:String?;if let i=a.firstIndex(of:">"),i+1<a.count{file=a[i+1];a.removeSubrange(i...i+1)};var captured="";let ctx=CommandContext(cwd:cwd,env:env,registry:registry,output:{x in captured+=x;if file == nil{output(x)}},error:error);let s=registry.execute(n,args:a,context:ctx);cwd=ctx.cwd;env=ctx.env;if let f=file{try? captured.write(to:URL(fileURLWithPath:cwd).appendingPathComponent(f),atomically:true,encoding:.utf8)};return s};private func allocate()->TermXPID{lock.lock();defer{lock.unlock()};nextPID+=1;return nextPID};public func startShell(cwd:String,env:[String:String],ptySlave:Int32,onExit:@escaping(Int32)->Void)throws->Int32{let p=allocate();DispatchQueue.global().async{onExit(0)};return p};public func signal(pid:Int32,_ sig:Int32){lock.lock();jobs[pid]?.cancel();jobs.removeValue(forKey:pid);lock.unlock()} }
public enum TermXEnvironment { public static func defaults(sandbox:String)->[String:String]{["HOME":"\(sandbox)/Documents","PATH":"/bin:\(sandbox)/Documents/wasm/bin:\(sandbox)/Documents/node/bin:\(sandbox)/Documents/python/bin","TERM":"xterm-256color","LANG":"en_US.UTF-8"]} }
